#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int numberOfGoodPartitions(std::vector<int>& nums) {
        std::unordered_map<int, int> last;
        for (int i = 0; i < (int)nums.size(); ++i) {
            last[nums[i]] = i;
        }
        long long MOD = 1000000007;
        int components = 0;
        int maxReach = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            maxReach = std::max(maxReach, last[nums[i]]);
            if (i == maxReach) {
                ++components;
            }
        }
        long long ans = 1;
        for (int i = 0; i < components - 1; ++i) {
            ans = (ans * 2) % MOD;
        }
        return ans;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numberOfGoodPartitions(int[] nums) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            last.put(nums[i], i);
        }
        int MOD = 1_000_000_007;
        int components = 0;
        int maxReach = 0;
        for (int i = 0; i < nums.length; i++) {
            maxReach = Math.max(maxReach, last.get(nums[i]));
            if (i == maxReach) {
                components++;
            }
        }
        long ans = 1;
        for (int i = 0; i < components - 1; i++) {
            ans = (ans * 2) % MOD;
        }
        return (int) ans;
    }
}

var numberOfGoodPartitions = function(nums) {
    const last = new Map();
    for (let i = 0; i < nums.length; i++) {
        last.set(nums[i], i);
    }
    const MOD = 1000000007n;
    let components = 0;
    let maxReach = 0;
    for (let i = 0; i < nums.length; i++) {
        maxReach = Math.max(maxReach, last.get(nums[i]));
        if (i === maxReach) {
            components++;
        }
    }
    let ans = 1n;
    for (let i = 0; i < components - 1; i++) {
        ans = (ans * 2n) % MOD;
    }
    return Number(ans);
};
